package in.recallradar;
import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/inventory") class InventoryController {private final InventoryService inventory;private final TenantService tenants;InventoryController(InventoryService i,TenantService t){inventory=i;tenants=t;}private Membership member(Authentication a,String org){return tenants.membership(UUID.fromString(a.getName()),org);}@GetMapping("/lots") List<InventoryLotResponse> lots(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org){return inventory.inventory(member(a,org));}@PostMapping("/lots") @ResponseStatus(HttpStatus.CREATED) InventoryLotResponse receive(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org,@RequestHeader(value="Idempotency-Key",required=false)String key,@Valid @RequestBody ReceiveLotRequest r){return inventory.receive(member(a,org),r,key);}@PostMapping("/lots/{id}/transfers") InventoryLotResponse transfer(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org,@RequestHeader(value="Idempotency-Key",required=false)String key,@PathVariable UUID id,@Valid @RequestBody TransferRequest r){return inventory.transfer(member(a,org),id,r,key);}@PostMapping("/lots/{id}/adjustments") InventoryLotResponse adjust(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org,@RequestHeader(value="Idempotency-Key",required=false)String key,@PathVariable UUID id,@Valid @RequestBody AdjustmentRequest r){return inventory.adjust(member(a,org),id,r,key);}@PostMapping("/lots/{id}/waste") InventoryLotResponse waste(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org,@RequestHeader(value="Idempotency-Key",required=false)String key,@PathVariable UUID id,@Valid @RequestBody StockReductionRequest r){return inventory.reduce(member(a,org),id,r,MovementType.WASTE,key);}@PostMapping("/lots/{id}/disposals") InventoryLotResponse dispose(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org,@RequestHeader(value="Idempotency-Key",required=false)String key,@PathVariable UUID id,@Valid @RequestBody StockReductionRequest r){return inventory.reduce(member(a,org),id,r,MovementType.DISPOSAL,key);}@GetMapping("/lots/{id}/traceability") TraceabilityResponse trace(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org,@PathVariable UUID id){return inventory.trace(member(a,org),id);}}
